CREATE TABLE private.organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public."user"(id),name text NOT NULL,slug text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private.memberships(organization_id uuid NOT NULL REFERENCES private.organizations(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public."user"(id),role text NOT NULL CHECK(role IN ('owner','administrator','staff')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(organization_id,user_id));
CREATE UNIQUE INDEX organization_single_owner ON private.memberships(organization_id) WHERE role='owner';
CREATE TABLE private.team_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES private.organizations(id),email text NOT NULL,role text NOT NULL CHECK(role IN ('administrator','staff')),token_hash text NOT NULL UNIQUE,accepted_at timestamptz,expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private.team_event_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES private.organizations(id),title text NOT NULL,slug text NOT NULL,duration integer NOT NULL CHECK(duration BETWEEN 5 AND 240),buffer integer NOT NULL DEFAULT 15 CHECK(buffer BETWEEN 0 AND 60),active boolean NOT NULL DEFAULT true,UNIQUE(organization_id,slug));
CREATE TABLE private.team_event_staff(event_id uuid NOT NULL REFERENCES private.team_event_types(id),user_id uuid NOT NULL REFERENCES public."user"(id),personal_event_id uuid NOT NULL REFERENCES public.event_types(id),last_assigned_at timestamptz,PRIMARY KEY(event_id,user_id));
ALTER TABLE public.bookings ADD COLUMN organization_id uuid REFERENCES private.organizations(id),ADD COLUMN team_event_id uuid REFERENCES private.team_event_types(id);
CREATE TABLE private.entitlement_overrides(user_id uuid PRIMARY KEY REFERENCES public."user"(id),plan text NOT NULL CHECK(plan IN ('free','pro','business','teams')),expires_at timestamptz NOT NULL,actor_id uuid NOT NULL,reason text NOT NULL);
CREATE TABLE private.subscription_prices(plan text NOT NULL CHECK(plan IN ('pro','business','teams')),period text NOT NULL CHECK(period IN ('monthly','annual')),stripe_price_id text NOT NULL,PRIMARY KEY(plan,period));
ALTER TABLE private.subscriptions ADD COLUMN seats integer NOT NULL DEFAULT 1 CHECK(seats>0);
CREATE TABLE private.host_payment_accounts(user_id uuid PRIMARY KEY REFERENCES public."user"(id),account_id text NOT NULL UNIQUE,charges_enabled boolean NOT NULL DEFAULT false,payouts_enabled boolean NOT NULL DEFAULT false,details_submitted boolean NOT NULL DEFAULT false,disconnected_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.event_types ADD COLUMN payment_mode text NOT NULL DEFAULT 'free' CHECK(payment_mode IN ('free','full','deposit')),ADD COLUMN price_cents integer NOT NULL DEFAULT 0 CHECK(price_cents>=0),ADD COLUMN deposit_cents integer NOT NULL DEFAULT 0 CHECK(deposit_cents>=0),ADD COLUMN refund_policy text NOT NULL DEFAULT '';
CREATE TABLE private.appointment_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public."user"(id),booking_id uuid REFERENCES public.bookings(id),event_id uuid NOT NULL REFERENCES public.event_types(id),account_id text NOT NULL,checkout_id text UNIQUE,payment_intent text,status text NOT NULL CHECK(status IN ('held','pending','paid','expired','failed','refunded','partially_refunded')),amount_cents integer NOT NULL CHECK(amount_cents>0),total_cents integer NOT NULL CHECK(total_cents>=amount_cents),refunded_cents integer NOT NULL DEFAULT 0,currency text NOT NULL DEFAULT 'usd',starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,hold_expires_at timestamptz NOT NULL,guest_ciphertext text NOT NULL,policy_snapshot text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX appointment_live_hold ON private.appointment_payments(event_id,starts_at) WHERE status IN ('held','pending');
CREATE TABLE private.appointment_payment_events(account_id text NOT NULL,event_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_id,event_id));
REVOKE ALL ON private.organizations,private.memberships,private.team_invites,private.team_event_types,private.team_event_staff,private.entitlement_overrides,private.subscription_prices,private.host_payment_accounts,private.appointment_payments,private.appointment_payment_events FROM public,anon,authenticated;
